package com.autoops.execution.service;import com.autoops.common.security.CurrentUser;import com.autoops.execution.entity.ApprovalRequest;import com.autoops.execution.repository.ApprovalRequestRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.List;@Service public class ApprovalService{private final ApprovalRequestRepository repo;private final CurrentUser current;public ApprovalService(ApprovalRequestRepository r,CurrentUser c){repo=r;current=c;}public List<ApprovalRequest> pending(){return repo.findByStatusOrderByIdAsc("PENDING");}@Transactional public ApprovalRequest decide(Long id,boolean approve,boolean highRiskConfirmed){var a=repo.findById(id).orElseThrow();if(!"PENDING".equals(a.getStatus()))throw new IllegalArgumentException("Approval already decided");if(approve&&!highRiskConfirmed)throw new IllegalArgumentException("Explicit high-risk confirmation required");a.setStatus(approve?"APPROVED":"REJECTED");a.setApprovedBy(current.id());a.setDecidedAt(Instant.now());return repo.save(a);}}
